function automatic void sliding_window_sum(int arr[], int k, ref int out[]);
  out = new[0];
  if (k <= 0 || k > arr.size()) return;
  out = new[arr.size() - k + 1];
  for (int i = 0; i < out.size(); i++) begin
    int s;
    s = 0;
    for (int j = 0; j < k; j++) s += arr[i+j];
    out[i] = s;
  end
endfunction

