function automatic void rotate_left(ref int arr[], int k);
  int n;
  int tmp[];
  n = arr.size();
  if (n == 0) return;
  k = k % n;
  if (k < 0) k += n;
  if (k == 0) return;
  tmp = new[k];
  for (int i = 0; i < k; i++) tmp[i] = arr[i];
  for (int i = k; i < n; i++) arr[i-k] = arr[i];
  for (int i = 0; i < k; i++) arr[n-k+i] = tmp[i];
endfunction

