    dyn = new[dyn.size() + 1](dyn);
    dyn[dyn.size() - 1] = v;
    q.push_back(v);
  endfunction

  function int remove_first();
    int v;
    if (q.size() == 0) return -1;
    v = q.pop_front();
    for (int i = 1; i < dyn.size(); i++) dyn[i-1] = dyn[i];
    dyn = new[dyn.size() - 1](dyn);
    return v;
  endfunction

  function int total();
    int s;
    s = 0;
    foreach (dyn[i]) s += dyn[i];
    return s;
  endfunction
endclass

